#!/usr/bin/env bash
# Generated by Antigravity CLI 1.5.15 (Gemini 4 Hydrogen (Medium))
#
# scripts/release-macos-local.sh - Build macOS DMG locally and attach to a GitHub release
#
# Fallback for when GitHub-hosted macOS runners are unavailable or fail.
# Checks out the release tag in a temporary detached worktree, builds the DMG
# via scripts/package-macos.sh, and uploads it to the GitHub release.

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"

TAG=""
REPO=""
ARCH="${ARCH:-$(uname -m)}"
DRY_RUN=0

usage() {
    cat <<EOF
Usage: $(basename "$0") [options] <tag>

Builds the macOS DMG for <tag> in a temporary detached worktree and uploads it
to the GitHub release.

Options:
  --repo <owner/repo>   GitHub repository (default: detected via gh)
  --arch <arch>         Target architecture: arm64 or x86_64 (default: host arch)
  --dry-run             Build DMG locally without uploading to GitHub
  -h, --help            Show this help message
EOF
    exit 0
}

while [[ $# -gt 0 ]]; do
    case "$1" in
        --repo)
            REPO="$2"
            shift 2
            ;;
        --arch)
            ARCH="$2"
            shift 2
            ;;
        --dry-run)
            DRY_RUN=1
            shift
            ;;
        -h|--help)
            usage
            ;;
        -*)
            echo "Error: Unknown option: $1" >&2
            echo "Run '$(basename "$0") --help' for usage." >&2
            exit 1
            ;;
        *)
            if [[ -n "$TAG" ]]; then
                echo "Error: Unexpected argument: $1" >&2
                exit 1
            fi
            TAG="$1"
            shift
            ;;
    esac
done

if [[ -z "$TAG" ]]; then
    echo "Error: Release tag is required." >&2
    echo "Run '$(basename "$0") --help' for usage." >&2
    exit 1
fi

if [[ "$(uname -s)" != "Darwin" ]]; then
    echo "Error: This script must be run on macOS (Darwin)." >&2
    exit 1
fi

if [[ "$ARCH" != "arm64" && "$ARCH" != "x86_64" ]]; then
    echo "Error: Unsupported architecture '$ARCH'. Supported: arm64, x86_64." >&2
    exit 1
fi

for cmd in git gh; do
    if ! command -v "$cmd" >/dev/null 2>&1; then
        echo "Error: Required command '$cmd' not found in PATH." >&2
        exit 1
    fi
done

if ! git rev-parse --verify "refs/tags/${TAG}" >/dev/null 2>&1; then
    echo "Error: Tag '$TAG' does not exist locally. Run 'git fetch --tags' first." >&2
    exit 1
fi

if [[ -z "$REPO" ]]; then
    REPO="$(gh repo view --json nameWithOwner -q .nameWithOwner)"
fi

if [[ "$DRY_RUN" -eq 0 ]]; then
    if ! gh release view "$TAG" --repo "$REPO" >/dev/null 2>&1; then
        echo "Error: GitHub release '$TAG' not found in '$REPO'." >&2
        exit 1
    fi
fi

TMP_ROOT="$(mktemp -d -t neverball_macos_release)"
WORKTREE_DIR="$TMP_ROOT/src"

cleanup() {
    if [[ -d "$WORKTREE_DIR" ]]; then
        git -C "$REPO_ROOT" worktree remove --force "$WORKTREE_DIR" >/dev/null 2>&1 || true
    fi
    rm -rf "$TMP_ROOT"
}
trap cleanup EXIT

echo "==> Creating temporary worktree for $TAG..."
git worktree add --detach "$WORKTREE_DIR" "refs/tags/${TAG}"

echo "==> Building macOS DMG ($ARCH)..."
(
    cd "$WORKTREE_DIR"
    ./scripts/package-macos.sh --arch "$ARCH"
)

DMG_FILES=("$WORKTREE_DIR"/build/macos/neverball-*.dmg)
if [[ ${#DMG_FILES[@]} -ne 1 || ! -f "${DMG_FILES[0]}" ]]; then
    echo "Error: Expected a single DMG in $WORKTREE_DIR/build/macos/, found ${#DMG_FILES[@]}." >&2
    exit 1
fi
DMG_PATH="${DMG_FILES[0]}"
echo "==> Built: $(basename "$DMG_PATH")"

if [[ "$DRY_RUN" -eq 1 ]]; then
    echo "==> Dry run enabled; skipping upload."
    exit 0
fi

echo "==> Uploading $(basename "$DMG_PATH") to $REPO release $TAG..."
gh release upload "$TAG" "$DMG_PATH" --repo "$REPO" --clobber

echo "==> Done."
